import React from "react";

class ResultItem extends React.Component {
    render() {
        return (
            <>
                <div className="item-back overflow-hidden p-5 mt-3 rounded-4">
                    <h2 className="text-center m-5 mt-0">Search Results</h2>
                    <a href="/profile/other/{{ $user->id }}" className="text-decoration-none text-reset">
                        <div className="row align-items-center mb-2 boder p-3 rounded-4">
                            <div className="col-auto">
                                <img src="{{ asset($user->img) }}" alt="arshia" className="rounded-circle border finded-img"/>
                            </div>
                            <div className="col">
                                <h5 className="mb-0">Mmd</h5>
                                <small className="text-color ">Family</small>
                            </div>
                        </div>
                    </a>
                </div>
            </>
        );
    }
}
export default ResultItem;
